class DataValidationStage(DataStage[pd.DataFrame, pd.DataFrame]):
    """Validates data for consistency, completeness, accuracy, and validity."""

    def __init__(self, required_columns: Optional[List[str]] = None,
                 column_types: Optional[Dict[str, type]] = None,
                 allow_nulls: bool = False):
        self.required_columns = required_columns or []
        self.column_types = column_types or {}
        self.allow_nulls = allow_nulls

    def validate_input(self, input_data: pd.DataFrame) -> bool:
        """Ensure input is a non-empty DataFrame."""
        return isinstance(input_data, pd.DataFrame) and not input_data.empty

    def execute(self, input_data: pd.DataFrame) -> StageResult[pd.DataFrame]:
        """Run comprehensive validation checks."""
        try:
            df = input_data.copy()

            # Check required columns
            missing_cols = set(self.required_columns) - set(df.columns)
            if missing_cols:
                raise ValidationError(f"Missing required columns: {missing_cols}")

            # Check column types
            for col, expected_type in self.column_types.items():
                if col in df.columns:
                    # Allow nullable types via pd.api.types
                    if not pd.api.types.is_dtype_equal(df[col].dtype, pd.api.types.pandas_dtype(expected_type)):
                        # Try coercion and check if all values are valid
                        try:
                            pd.to_numeric(df[col], errors='raise')
                        except (ValueError, TypeError):
                            raise ValidationError(f"Column '{col}' cannot be coerced to {expected_type}.")

            # Check completeness (no nulls if disallowed)
            if not self.allow_nulls:
                null_counts = df.isnull().sum()
                if null_counts.any():
                    raise ValidationError(f"Null values found in columns: {null_counts[null_counts > 0].index.tolist()}")

            logger.info("Validation passed successfully.")
            return StageResult(status=StageStatus.COMPLETED, data=df)

        except ValidationError as e:
            logger.error(f"Validation failed: {e}")
            return StageResult(status=StageStatus.FAILED, error=str(e))
        except Exception as e:
            logger.error(f"Unexpected validation error: {e}")
            return StageResult(status=StageStatus.FAILED, error=str(e))


