# Data Ingestion Module
class IngestionStage(DataStage[None, pd.DataFrame]):
    """Ingests data from various sources (CSV, Excel, DB) into a DataFrame."""

    def __init__(
        self,
        source_path: Optional[str] = None,
        source_type: Optional[str] = None,
        db_url: Optional[str] = None,
        query: Optional[str] = None,
    ):
        self.source_path = source_path
        self.source_type = source_type or self._infer_type(source_path)
        self.db_url = db_url
        self.query = query

    def _infer_type(self, path: Optional[str]) -> str:
        if not path:
            return "csv"
        ext = os.path.splitext(path)[1].lower()
        if ext in (".csv",):
            return "csv"
        elif ext in (".xlsx", ".xls"):
            return "excel"
        else:
            return "csv"

    @property
    def name(self) -> str:
        return "IngestionStage"

    def execute(self, input_data: None) -> StageResult[pd.DataFrame]:
        try:
            logger.info(f"Starting data ingestion from {self.source_type}...")
            if self.source_type == "csv":
                if not self.source_path:
                    raise ValueError("CSV source path required")
                df = pd.read_csv(self.source_path)
            elif self.source_type == "excel":
                if not self.source_path:
                    raise ValueError("Excel source path required")
                df = pd.read_excel(self.source_path)
            elif self.source_type == "database":
                if not self.db_url or not self.query:
                    raise ValueError("Database URL and query required")
                df = pd.read_sql(self.query, self.db_url)
            else:
                raise ValueError(f"Unsupported source type: {self.source_type}")

            # Basic format validation
            if df.empty:
                logger.warning("Ingested DataFrame is empty.")
            logger.info(f"Ingested {len(df)} rows and {len(df.columns)} columns.")
