# Data Validation Module
class ValidationStage(DataStage[pd.DataFrame, pd.DataFrame]):
    """Validates data for consistency, completeness, accuracy, and validity."""

    def __init__(
        self,
        required_columns: Optional[List[str]] = None,
        column_types: Optional[Dict[str, type]] = None,
        non_null_columns: Optional[List[str]] = None,
        custom_validators: Optional[List[Callable[[pd.DataFrame], List[str]]]] = None,
    ):
        self.required_columns = required_columns or []
        self.column_types = column_types or {}
        self.non_null_columns = non_null_columns or []
        self.custom_validators = custom_validators or []

    @property
    def name(self) -> str:
        return "ValidationStage"

    def execute(self, input_data: pd.DataFrame) -> StageResult[pd.DataFrame]:
        errors: List[str] = []
        df = input_data.copy()

        # Check required columns
        missing_cols = set(self.required_columns) - set(df.columns)
        if missing_cols:
            errors.append(f"Missing required columns: {missing_cols}")

        # Check column types
        for col, expected_type in self.column_types.items():
            if col in df.columns:
                try:
                    df[col] = df[col].astype(expected_type)
                except (ValueError, TypeError):
                    errors.append(f"Column '{col}' cannot be cast to {expected_type.__name__}")

        # Check non-null constraints
        for col in self.non_null_columns:
            if col in df.columns:
                null_count = df[col].isnull().sum()
                if null_count > 0:
                    errors.append(f"Column '{col}' has {null_count} null values")

        # Run custom validators
        for validator in self.custom_validators:
            try:
                errors.extend(validator(df))
            except Exception as e:
                errors.append(f"Custom validator error: {e}")

        if errors:
            logger.error(f"Validation failed with {len(errors)} errors")
            return StageResult(status=StageStatus.FAILED, error="; ".join(errors))

        logger.info("Validation passed successfully.")
        return StageResult(status=StageStatus.COMPLETED, data=df)


